RECIPE_CATEGORIES = ["main", "dessert", "breakfast", "salad", "snack", "beverage"]
CUISINES = ["Indian", "Italian", "Japanese", "Thai", "Mexican", "Chinese", "American", "French", "British", "Healthy"]

def get_recipe_recommendations(query="", cuisine=None, category=None, count=5):
    results = RECIPES
    if cuisine:
        results = [r for r in results if r["cuisine"].lower() == cuisine.lower()]
    if category:
        results = [r for r in results if r["category"].lower() == category.lower()]
    if query:
        q = query.lower()
        results = [r for r in results if q in r["name"].lower() or any(q in t for t in r["tags"]) or any(q in i for i in r["ingredients"])]
    if not results:
        results = RECIPES
    import random
    random.shuffle(results)
    return results[:count]

def format_recipe_for_ai(recipes):
    text = "Here are my recipe recommendations:\n\n"
    for i, r in enumerate(recipes, 1):
        text += f"**{i}. {r['name']}** ({r['cuisine']})\n"
        text += f"   Difficulty: {r['difficulty']} | Time: {r['time']}\n"
        text += f"   Ingredients: {', '.join(r['ingredients'][:6])}...\n"
        text += f"   Steps:\n"
        for j, step in enumerate(r['steps'], 1):
            text += f"   {j}. {step}\n"
        text += "\n"
    return text
